@layer components {
  /* Component-tier color token aliases */
  :root {
    --shelf-feed-page-bgColor-surface: var(--shelf-bgColor-surface);
    --shelf-feed-page-fgColor-heading: var(--shelf-fgColor-default);
    --shelf-feed-page-fgColor-title: var(--shelf-fgColor-default);
    --shelf-feed-page-fgColor-description: var(--shelf-fgColor-muted);
    --shelf-feed-page-bgColor-card: var(--shelf-bgColor-elevated);
    --shelf-feed-page-borderColor-card: var(--shelf-borderColor-default);
  }

  [data-theme="dark"] {
    --shelf-feed-page-bgColor-surface: var(--shelf-bgColor-surface);
    --shelf-feed-page-fgColor-heading: var(--shelf-fgColor-default);
    --shelf-feed-page-fgColor-title: var(--shelf-fgColor-default);
    --shelf-feed-page-fgColor-description: var(--shelf-fgColor-muted);
    --shelf-feed-page-bgColor-card: var(--shelf-bgColor-elevated);
    --shelf-feed-page-borderColor-card: var(--shelf-borderColor-default);
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --shelf-feed-page-bgColor-surface: var(--shelf-bgColor-surface);
      --shelf-feed-page-fgColor-heading: var(--shelf-fgColor-default);
      --shelf-feed-page-fgColor-title: var(--shelf-fgColor-default);
      --shelf-feed-page-fgColor-description: var(--shelf-fgColor-muted);
      --shelf-feed-page-bgColor-card: var(--shelf-bgColor-elevated);
      --shelf-feed-page-borderColor-card: var(--shelf-borderColor-default);
    }
  }

  .feed-page {
    max-width: var(--shelf-size-content-max);
    background-color: var(--shelf-feed-page-bgColor-surface);
  }

  .feed-page-heading {
    color: var(--shelf-feed-page-fgColor-heading);
    font-size: var(--shelf-fontSize-xl);
    font-weight: var(--shelf-fontWeight-bold);
  }

  .feed-item-list {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background-color: var(--shelf-feed-page-bgColor-card);
    border: var(--shelf-borderWidth-default) solid var(--shelf-feed-page-borderColor-card);
    border-radius: var(--shelf-borderRadius-md);
    padding: var(--shelf-space-md);
  }

  .feed-item-title {
    color: var(--shelf-feed-page-fgColor-title);
    font-size: var(--shelf-fontSize-md);
    font-weight: var(--shelf-fontWeight-semibold);
  }

  .feed-item-description {
    color: var(--shelf-feed-page-fgColor-description);
    font-size: var(--shelf-fontSize-sm);
  }
}
